      "item": "i01",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "certainty",
          "detail": "“今年一定会遭遇重大失败”是宿命化的确定性断言，应删除。"
        },
        {
          "dimension": "consistency",
          "detail": "换年换月的历法约定不能推出个人成败，末句与条目主题无关。"
        },
        {
          "dimension": "theme_direction",
          "detail": "末句明确表达重大受阻，与四个主题均为中性的方向不一致。"
        }
      ],
      "reason": "换柱规则基本符合子平八字常用约定，但附加了无依据的确定性失败预言。"
    },
    {
      "item": "i02",
      "verdict": "reject",
      "issues": [
        {
          "dimension": "medical_legal_finance",
          "detail": "“身体已有慢性疾病”构成确定性医疗诊断，“不必就医也会自愈”还作出了无需就医及自行康复的保证。"
        },
        {
          "dimension": "certainty",
          "detail": "将地支刑直接断为已经患病并必会自愈，属于确定性断言。"
        },
        {
          "dimension": "tradition",
          "detail": "地支刑是地支之间的传统关系，不宜笼统表述为“干支之间”的关系。"
        }
      ],
      "reason": "条目含明确的医疗诊断和自愈保证，且对地支刑的关系范围表述不准。"
    },
    {
      "item": "i03",
      "verdict": "reject",
      "issues": [
        {
          "dimension": "consistency",
          "detail": "key 和关键词为“壬”，正文却解释“丁”，释义对象不符。"
        },
        {
          "dimension": "tradition",
          "detail": "壬为阳水，丁为阴火，是不同天干，不能以丁的释义替代壬。"
        }
      ],
      "reason": "正文写错天干对象，与条目 key 不符。"
    },
    {
      "item": "i04",
      "verdict": "pass",
